import logging
import os
import time
from datetime import datetime
import traceback
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from taf.trafficgenerator.iperf.facade import IperfFacade
from taf.ue.plugin.mtk.exceptions import (IperfTrafficError, IperfPortInvalid, TrafficAppNotSupport, InvalidIperfLog,
                                          BiDirectionNotSupported)
from taf.ue.plugin.mtk.data_transfer.config import (UeDataTransferConfig, AppserverDataTransferConfig,
                                                    IperfDataTransferOptionsFactory)


class MTKDataTransfer(LteDataTransfer):

    def __init__(self, alias, dt_definition, configuration, logger_name='taf_ue'):
        """
                Basic initialization.

                :param alias: Alias to be assigned to DataTransfer object
                :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
                :param configuration: tool dependant configuration provided by UE instance
                needed for data transfer operations
                """
        super(MTKDataTransfer, self).__init__(alias, dt_definition, configuration, logger_name)

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        raise NotImplementedError

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        raise NotImplementedError

    def await_finish(self, sleep_time=1):
        """
        Check if data transfer is finished

        :return: boolean
        """
        raise NotImplementedError

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        raise NotImplementedError

    def check_data_transfer(self):
        """Check if data transfer is progressing"""
        raise NotImplementedError

    def reset_statistics(self):
        """
        Reset data transfer statistics on UE.

        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`:
        if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`:
        if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`:
        If reset data transfer statistics failed
        """
        raise NotImplementedError

    def get_data_transfer_statistics(self):
        """Get all statistics of data transfer (intermediate results on timeline & final result)"""
        raise NotImplementedError

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="iperf", *args, **kwargs):
        """
        Abstract method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from
        'dt.start()' to 'dt.stop()' if data transfer is already finished

        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: Kbits/sec
        """
        raise NotImplementedError

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        raise NotImplementedError


class MTKIperfDataTransfer(MTKDataTransfer):
    _IPERF_SERVER_LOG_FILE = 'iperf_server_{host}_{port}_{timestamp}.log'

    def __init__(self, alias, dt_definition, configuration, checkthroughput,
                 ue, appserver, iperf_port, logger_name='taf_ue'):
        """
                Basic initialization.

                :param alias: Alias to be assigned to DataTransfer object
                :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
                :param configuration: tool dependant configuration provided by UE instance
                needed for data transfer operations
                :param checkthroughput: ThroughputChecker object
                :param ue: UE object - MediaTek UE instance
                :param appserver: dict - definition of appserver
                :param iperf_port: int - port for iperf tool
                """
        super(MTKIperfDataTransfer, self).__init__(alias, dt_definition, configuration, logger_name)
        self._throughput_checker = checkthroughput
        self._iperf_port = iperf_port
        self._appserver = appserver
        self._ue = ue
        self._ue_dt_config = UeDataTransferConfig(dt_definition=dt_definition,
                                                  configuration=configuration,
                                                  ue_ip=ue.ue_ip)
        self._appserver_dt_config = AppserverDataTransferConfig(dt_definition=dt_definition,
                                                                configuration=configuration,
                                                                appserver_name=appserver)
        self._iperf_options_factory = IperfDataTransferOptionsFactory()
        self._iperf = IperfFacade()
        self._iperf_server = None
        self._iperf_client = None
        self._iperf_instances = None
        self._iperf_server_config = None
        self._iperf_client_config = None
        self._test_logs_dir = self._ue_dt_config.test_logs_dir
        self._iperf_log_filename = None
        self._iperf_log_file_path = None

        self._is_client_adb_shell = False
        self._is_server_adb_shell = False

    @property
    def iperf_log_file_path(self):
        self._iperf_log_file_path = os.path.join(self._test_logs_dir, self._iperf_log_filename)
        return self._iperf_log_file_path

    def _get_iperf_port(self, iperf_port):
        iperf_ports_from_config = self._get_iperf_ports_from_config()
        iperf_ports_from_config = [int(each_iperf_port) for each_iperf_port in iperf_ports_from_config]
        iperf_port = iperf_port if iperf_port is None else int(iperf_port)
        if iperf_port:
            if iperf_ports_from_config:
                return iperf_port
            else:
                raise IperfPortInvalid("iperf_ports should not be empty in config")

        if iperf_ports_from_config:
            return iperf_ports_from_config[0]

        return 5001

    def _get_iperf_ports_from_config(self):
        return self._iperf_server_config.host_config['iperf_ports']

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        self._iperf.start(self._iperf_instances)
        self._throughput_checker.setup()

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        self._iperf.stop(self._iperf_instances)
        self._iperf.teardown_iperfs()

    def await_finish(self, sleep_time=1):
        """
        Check if data transfer is finished

        :return: boolean
        """
        try:
            while True:
                if not self.is_running():
                    break
                time.sleep(sleep_time)
        except Exception:
            raise IperfTrafficError(traceback.format_exc())
        logging.info('Dt "{}": finished'.format(self.name))
        self._iperf.stop(self._iperf_instances)
        self._iperf.teardown_iperfs()

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        check_result = []
        for iperf in self._iperf_instances:
            try:
                check_result.append(self._iperf.is_running(iperf))
            except Exception as err_info:
                msg = "data transfer is not running, root cause: {}. \r\n traceback is {}"
                logging.warning(msg.format(err_info, traceback.format_exc()))
                return False
        return False not in check_result

    def check_data_transfer(self):
        """Check if data transfer is progressing"""
        return self.is_running()

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="iperf", *args, **kwargs):
        """
        Abstract method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from
        'dt.start()' to 'dt.stop()' if data transfer is already finished

        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: Kbits/sec
        """
        if tput_collection_src != "iperf":
            raise TrafficAppNotSupport('{} is not supported.'.format(tput_collection_src))
        # cause the NAA released iperf3 binary is 3.1.7 for CentOS platform, the output is not bitrate but bandwidth
        # so force to set the key column as bandwidth for uplink transport
        word = self._lookup_key_word_from_log(['Bandwidth', 'Bitrate'])
        if not word:
            raise InvalidIperfLog("Neither Bandwidth nor Bitrate in log")
        time_range = self._generate_time_range(omit=omit, end=end)
        return self._get_iperf_average_throughput(tput_column=word.lower(), time_range=time_range)

    def _lookup_key_word_from_log(self, words):
        with open(self.iperf_log_file_path, 'r') as f:
            content = f.read()
            for word in words:
                if word in content:
                    return word
            return None

    @staticmethod
    def _generate_time_range(omit=0, end=0):
        omit = int(omit)
        end = int(end)
        if end and (omit >= end):
            raise ValueError("end must be greater than omit if end is not equal 0.")
        if omit == 0 and end == 0:
            time_range = None
        elif end == 0:
            time_range = [omit, ]
        else:
            time_range = [omit, end]
        return time_range

    def _get_iperf_average_throughput(self, tput_column=None, time_range=None):
        if self._iperf_server_config.version == '3':
            self._throughput_checker.create_iperf3_throughput(file_path=self.iperf_log_file_path,
                                                              protocol=self._iperf_server_config.dt_definition['protocol'],
                                                              time_range=time_range,
                                                              column=tput_column)
        else:
            self._throughput_checker.create_iperf_throughput(file_path=self.iperf_log_file_path,
                                                             protocol=self._iperf_server_config.dt_definition['protocol'],
                                                             time_range=time_range,
                                                             column=tput_column)
        return self._throughput_checker.get_average_throughput()

    def reset_statistics(self):
        """
        Reset data transfer statistics on UE.

        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`:
        if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`:
        if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`:
        If reset data transfer statistics failed
        """
        logging.info("Skip reset_statistics method.")

    def get_data_transfer_statistics(self):
        """Get all statistics of data transfer (intermediate results on timeline & final result)"""
        logging.info("Skip get_data_transfer_statistics method.")

    def get_data_transfer_raw_data(self, output_file=None):
        """Get all raw statistics of data transfer final result"""
        with open(self.iperf_log_file_path, 'r') as content_file:
            raw_data = content_file.read()
        if output_file:
            self._save_file(raw_data, output_file)
        return raw_data

    @staticmethod
    def _save_file(data, file_path):
        if os.path.isfile(file_path):
            logging.debug('The old file {} is removed.'.format(file_path))
            os.remove(file_path)

        with open(file_path, 'w') as target_file:
            target_file.write(data)

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        logging.info("Skip get_datagram_loss method.")

    def _create_iperf_instance(self):
        self._iperf_server_cmd_options = self._iperf_options_factory.create_iperf_server_options(
            config=self._configuration, dt_definition=self._dt_definition, port=self._iperf_port,
            bind=self._iperf_server_config.bind)

        self._iperf_client_cmd_options = self._iperf_options_factory.create_iperf_client_options(
            config=self._configuration, dt_definition=self._dt_definition, port=self._iperf_port,
            bind=self._iperf_client_config.bind, client=self._iperf_server_config.bind)

        self._iperf_server = self._create_iperf_server_instance()
        self._iperf_client = self._create_iperf_client_instance()
        self._iperf_instances = [self._iperf_server, self._iperf_client]

    def _create_iperf_client_instance_only(self):
        if self.direction == 'ul':
            client_bind = None
        elif self.direction == 'dl':
            client_bind = self._iperf_client_config.bind
        else:
            raise BiDirectionNotSupported("MTK support 'ul' or 'dl' only.")
        self._iperf_client_cmd_options = self._iperf_options_factory.create_iperf_client_options(
            config=self._configuration, dt_definition=self._dt_definition, port=self._iperf_port,
            bind=client_bind, client=self._iperf_server_config.bind)
        self._iperf_client = self._create_iperf_client_instance()
        self._iperf_instances = [self._iperf_client]

    def _prepare_iperf(self):
        self._iperf_log_filename = self._IPERF_SERVER_LOG_FILE.format(
            host=self._iperf_server_config.bind,
            port=self._iperf_port,
            timestamp=datetime.today().strftime("%Y%m%dT%H%M%S%f"))

        self._create_iperf_client_instance_only() if self._ue.iperf_client_only() else self._create_iperf_instance()
        self._iperf.setup_iperfs(self._iperf_instances)

    def _create_iperf_server_instance(self):
        serial_number = self._iperf_server_config.serial_number if self._is_server_adb_shell else None
        if self._iperf_server_config.version == '3':
            return self._iperf.create_iperf3_server(
                cmd_options=self._iperf_server_cmd_options,
                iperf_path=self._iperf_server_config.iperf_path,
                adb=self._is_server_adb_shell,
                serial_number=serial_number,
                log_path=self.iperf_log_file_path,
                host_configuration=self._iperf_server_config.connection)

        return self._iperf.create_iperf_server(
            cmd_options=self._iperf_server_cmd_options,
            iperf_path=self._iperf_server_config.iperf_path,
            adb=self._is_server_adb_shell,
            serial_number=serial_number,
            log_path=self.iperf_log_file_path,
            host_configuration=self._iperf_server_config.connection)

    def _create_iperf_client_instance(self):
        serial_number = self._iperf_client_config.serial_number if self._is_client_adb_shell else None
        if self._iperf_client_config.version == '3':
            return self._iperf.create_iperf3_client(
                cmd_options=self._iperf_client_cmd_options,
                iperf_path=self._iperf_client_config.iperf_path,
                adb=self._is_client_adb_shell,
                serial_number=serial_number,
                log_path=self.iperf_log_file_path,
                host_configuration=self._iperf_client_config.connection)

        return self._iperf.create_iperf_client(
            cmd_options=self._iperf_client_cmd_options,
            iperf_path=self._iperf_client_config.iperf_path,
            adb=self._is_client_adb_shell,
            serial_number=serial_number,
            log_path=self.iperf_log_file_path,
            host_configuration=self._iperf_client_config.connection)


class MTKIperfUpLinkDataTransfer(MTKIperfDataTransfer):
    """Object responsible for managing data transfer."""

    def __init__(self, alias, dt_definition, configuration, checkthroughput, ue,
                 is_client_adb_shell=False, appserver=None, iperf_port=None, logger_name='taf_ue'):
        """

        :param alias: Alias to be assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param is_client_adb_shell: boolean - True or False
        :param checkthroughput: FakeThoughputChecker object
        :param ue: UE object - MediaTek UE instance
        :param appserver: dict - definition of appserver
        :param iperf_port: int - port for iperf tool
        """
        super(MTKIperfUpLinkDataTransfer, self).__init__(alias, dt_definition, configuration, checkthroughput, ue,
                                                         appserver, iperf_port, logger_name)
        self._is_client_adb_shell = is_client_adb_shell
        self._iperf_server_config = self._appserver_dt_config
        self._iperf_client_config = self._ue_dt_config
        self._iperf_port = self._get_iperf_port(iperf_port)
        self._prepare_iperf()


